<script setup lang="ts">
import { onMounted, onUnmounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { api, type WorkflowDetail, type WorkflowStage } from "../api/client";
import AdminLayout from "../components/AdminLayout.vue";
import AppIcon from "../components/AppIcon.vue";
import AppFooter from "../components/AppFooter.vue";
import { useToast } from "../composables/useToast";
const route=useRoute(),router=useRouter(),{notify}=useToast();
const detail=ref<WorkflowDetail|null>(null),loading=ref(true),error=ref(""),deleting=ref(false);
let previousStatus:string|null=null;
let pollHandle:ReturnType<typeof setInterval>|undefined;
const statuses:Record<string,string>={pending:"等待执行",running:"执行中",succeeded:"成功",failed:"失败",skipped:"已跳过"};
const sources:Record<string,string>={startup:"服务启动",scheduled:"定时任务",manual:"手动生成","save-and-generate":"保存并生成"};
const label=(v:string)=>statuses[v]||v,sourceLabel=(v:string)=>sources[v]||v;
const dateLabel=(v:string|null)=>v?new Date(v).toLocaleString():"—";
function durationLabel(s:WorkflowStage){const ms=s.duration_ms??(s.started_at?Date.now()-new Date(s.started_at).getTime():null);if(ms===null)return"—";return ms<1000?ms+" ms":ms<60000?(ms/1000).toFixed(1)+" 秒":Math.floor(ms/60000)+" 分 "+Math.floor(ms%60000/1000)+" 秒";}
async function load(){try{const session=await api.session();if(!session.loggedIn){await router.replace("/admin/login");return;}const next=await api.workflowDetail(Number(route.params.id));if(previousStatus!==null&&(previousStatus==="running"||previousStatus==="pending")&&(next.run.status==="succeeded"||next.run.status==="failed")){notify(next.run.status==="succeeded"?`工作流 #${next.run.id} 已执行完成`:`工作流 #${next.run.id} 执行失败：${next.run.error||next.run.message||"请查看执行详情"}`,next.run.status==="succeeded"?"success":"error",6500);}previousStatus=next.run.status;detail.value=next;error.value="";}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{loading.value=false;}}
async function deleteRun(){if(!detail.value||deleting.value)return;const run=detail.value.run;if(run.status==="running"||run.status==="pending"){notify("工作流仍在等待或执行中，不能删除。","warning");return;}if(!window.confirm(`确定删除工作流执行记录 #${run.id} 吗？其阶段详情也会一并删除，此操作不可撤销。`))return;deleting.value=true;try{await api.deleteWorkflow(run.id);notify(`工作流执行记录 #${run.id} 已删除`,"success");await router.replace("/admin/workflows");}catch(e){notify(e instanceof Error?e.message:String(e),"error");}finally{deleting.value=false;}}
onMounted(()=>{void load();pollHandle=setInterval(()=>void load(),3000);});onUnmounted(()=>{if(pollHandle)clearInterval(pollHandle);});
</script>
<template>
<AdminLayout active="workflow" title="工作流详情" subtitle="查看本次执行的整体状态、各阶段结果与失败原因。">
<template #actions><button v-if="detail && detail.run.status !== 'running' && detail.run.status !== 'pending'" class="delete-button" type="button" :disabled="deleting" @click="deleteRun"><AppIcon :name="deleting?'loader-circle':'trash-2'" :size="15" :class="{spinning:deleting}"/> {{deleting?"删除中…":"删除记录"}}</button><RouterLink class="back-link" to="/admin/workflows"><AppIcon name="arrow-left" :size="15"/> 返回工作流</RouterLink></template>
<div class="detail-page">
<div v-if="error" class="error-panel" role="alert"><strong>读取执行详情失败</strong><span>{{error}}</span><button type="button" @click="load()">重试</button></div>
<section v-if="detail" class="detail-panel"><div class="panel-heading"><div><p class="eyebrow">EXECUTION #{{detail.run.id}}</p><h2>PAC 生成工作流</h2><p class="muted">固定工作流标识：pac-generation</p></div><span class="status" :class="detail.run.status"><AppIcon v-if="detail.run.status==='running'||detail.run.status==='pending'" name="loader-circle" :size="13" class="spinning"/>{{label(detail.run.status)}}</span></div>
<div class="meta-grid"><div><span>执行编号</span><strong>#{{detail.run.id}}</strong></div><div><span>触发方式</span><strong>{{sourceLabel(detail.run.source)}}</strong></div><div><span>生成模式</span><strong>{{detail.run.mode==="remote"?"远程规则":"自定义规则"}}</strong></div><div><span>开始时间</span><strong>{{dateLabel(detail.run.started_at||detail.run.created_at)}}</strong></div><div><span>结束时间</span><strong>{{dateLabel(detail.run.finished_at)}}</strong></div><div><span>总耗时</span><strong>{{detail.run.duration_ms==null?(detail.run.status==="running"?"执行中":"—"):detail.run.duration_ms+" ms"}}</strong></div></div>
<div class="result-message"><strong>执行结果</strong><p>{{detail.run.message||"暂无结果信息"}}</p></div><div v-if="detail.run.error" class="failure-message"><strong><AppIcon name="circle-alert" :size="16"/> 失败原因</strong><pre>{{detail.run.error}}</pre></div></section>
<section v-if="detail" class="detail-panel"><div class="panel-heading"><div><p class="eyebrow">STAGE TIMELINE</p><h2>阶段执行情况</h2><p class="muted">阶段记录由服务端持久化，刷新页面不会丢失。</p></div><span class="muted">{{detail.stages.length}} 个阶段</span></div>
<ol class="stage-list"><li v-for="(stage,index) in detail.stages" :key="stage.id" class="stage-item"><span class="stage-marker" :class="stage.status"><AppIcon :name="stage.status==='succeeded'?'check':stage.status==='failed'?'x':stage.status==='running'?'loader-circle':stage.status==='pending'?'loader-circle':'circle'" :size="16" :class="{spinning:stage.status==='running'||stage.status==='pending'}"/></span><div class="stage-body"><div class="stage-heading"><div><span class="stage-number">阶段 {{index+1}}</span><h3>{{stage.name}}</h3></div><span class="status" :class="stage.status">{{label(stage.status)}}</span></div><p>{{stage.message||"暂无阶段说明"}}</p><div class="stage-meta"><span>开始：{{dateLabel(stage.started_at)}}</span><span>结束：{{dateLabel(stage.finished_at)}}</span><span>耗时：{{durationLabel(stage)}}</span></div><pre v-if="stage.error" class="stage-error">{{stage.error}}</pre></div></li><li v-if="!detail.stages.length" class="no-stages"><AppIcon name="info" :size="17"/> 此执行记录没有阶段数据（例如升级前创建的历史任务）。</li></ol></section>
<div v-else-if="loading" class="detail-panel loading"><AppIcon name="loader-circle" :size="20"/> 正在加载执行详情…</div><AppFooter/></div>
</AdminLayout>
</template>
<style scoped>
.detail-page{display:grid;gap:18px}.detail-panel{min-width:0;padding:22px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:var(--shadow-sm,0 4px 18px #00000008)}.panel-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:20px}.panel-heading h2{margin:0;color:var(--text);font-size:19px}.eyebrow{margin:0 0 6px;color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.13em}.muted{color:var(--muted);font-size:12px}.status{display:inline-flex;padding:5px 9px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:11px;font-weight:800;white-space:nowrap}.status.running,.status.pending{color:var(--accent)}.status.succeeded{color:var(--green)}.status.failed{color:var(--red)}.meta-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;padding:15px 0;border-block:1px solid var(--line)}.meta-grid div{display:grid;gap:6px;min-width:0}.meta-grid span{color:var(--muted);font-size:11px}.meta-grid strong{color:var(--text);font-size:12px;overflow-wrap:anywhere}.result-message{padding:15px 0}.result-message strong{font-size:13px}.result-message p{margin:7px 0 0;color:var(--muted);font-size:13px;overflow-wrap:anywhere}.failure-message,.stage-error{padding:13px;border:1px solid color-mix(in srgb,var(--red) 30%,var(--line));border-radius:8px;background:var(--red-soft);color:var(--red)}.failure-message strong{display:flex;align-items:center;gap:7px}.failure-message pre,.stage-error{margin:8px 0 0;font:inherit;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.stage-list{list-style:none;margin:0;padding:0}.stage-item{display:flex;gap:13px;position:relative;padding-bottom:24px}.stage-item:not(:last-child):before{content:"";position:absolute;left:15px;top:32px;bottom:0;width:1px;background:var(--line)}.stage-marker{z-index:1;display:grid;place-items:center;flex:0 0 32px;width:32px;height:32px;border:1px solid var(--line);border-radius:50%;background:var(--surface-2);color:var(--muted)}.stage-marker.succeeded{color:var(--green)}.stage-marker.failed{color:var(--red)}.stage-marker.running{color:var(--accent)}.stage-body{flex:1;min-width:0;padding:4px 0}.stage-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.stage-heading h3{margin:3px 0 0;color:var(--text);font-size:14px}.stage-number{color:var(--muted);font-size:10px}.stage-body p{margin:9px 0;color:var(--muted);font-size:12px;line-height:1.6;overflow-wrap:anywhere}.stage-meta{display:flex;flex-wrap:wrap;gap:8px 18px;color:var(--muted);font-size:11px}.no-stages,.loading{display:flex;align-items:center;gap:10px;padding:20px;color:var(--muted);font-size:13px}.error-panel{display:grid;gap:8px;padding:14px;border:1px solid var(--red);border-radius:10px;color:var(--red);font-size:12px}.back-link,.delete-button{display:inline-flex;align-items:center;gap:7px;min-height:36px;padding:0 12px;border:1px solid var(--line);border-radius:8px;color:var(--text);text-decoration:none;font-size:12px;font-weight:700;background:var(--surface);cursor:pointer}.delete-button{color:var(--red)}.delete-button:disabled{opacity:.55;cursor:not-allowed}.status{gap:5px}.spinning{animation:spin .9s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spinning{animation-duration:2.5s}}@media(max-width:650px){.detail-panel{padding:15px}.meta-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.stage-heading{align-items:flex-start}}
</style>